export const positionSummaries = (["QB", "RB", "WR", "TE"] as const).map((position) => {
  const rows = demoForecasts.filter((row) => row.position === position);
  const average = (field: "floor" | "median" | "ceiling") => rows.reduce((sum, row) => sum + row.original[field], 0) / Math.max(rows.length, 1);
  return {
    position,
    rows: rows.length,
    averageFloor: average("floor"),
    averageMedian: average("median"),
    averageCeiling: average("ceiling"),
  };
});

